head.script:
scwin.onpageload = function() {
    model = {};
    model.setValue = function(xpath, xpathVal, instanceName) {
        WebSquare.ModelUtil.setInstanceValue({
            xpath: xpath,
            instanceId: instanceName,
            value: xpathVal
        });
    };
}		
scwin.btn_dataSet_onclick = function(e) {
    var nodeObj = WebSquare.xml.parse("<gridList_row/>");
    var targetNodeStr = "root/ui/gridList";
    var instanceName = null;
    var mode = "append";
    //WebSquare.ModelUtil.setInstanceNode({doc:nodeObj, xpath:targetNodeStr, instanceId:instanceName, mode:"append"});
    for (var i = 1; i < 10; i++) {
        WebSquare.ModelUtil.setInstanceNode({
            doc: nodeObj,
            xpath: targetNodeStr,
            instanceId: instanceName,
            mode: "append"
        });
        model.setValue("root/ui/gridList/gridList_row[" + i + "]/col01", (i % 4));
        model.setValue("root/ui/gridList/gridList_row[" + i + "]/col02", "20191111");
        model.setValue("root/ui/gridList/gridList_row[" + i + "]/col03", ((i % 4) == 1) ? "Y" : "N");
        model.setValue("root/ui/gridList/gridList_row[" + i + "]/col04", (i + 1) * (i % 5) * 1230);
        model.setValue("root/ui/gridList/gridList_row[" + i + "]/col05", (i + 1) * (i % 4) * 970);
        model.setValue("root/ui/gridList/gridList_row[" + i + "]/col06", (i + 1) * (i % 3) * 320);
        model.setValue("root/ui/gridList/gridList_row[" + i + "]/col07", (i + 1) * (i % 2) * 320);
    }
};
scwin.getErrorLog = function() {
    var temp = WebSquare.logger.getErrorLog();
    return temp;
    // return temp.indexOf("error문구");
    // return temp.indexOf("error");
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_dataSet').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.getErrorLog() == ''", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
